  internal static BOrdinaryGeometryBinding Geometry(BDirectAttackBasicLoopBinding b,JObject asset=null){asset=asset??Asset();long span=(long)asset["frontMm"][0]-(long)asset["backMm"][0]+1000;var g=BOrdinaryGeometrySnapshot.Read(asset,BDirectAttackInput.Digest(asset));var p=new JObject{["version"]=BOrdinaryGeometryBinding.Version,["geometryHash"]=g.Hash,["inputHash"]=b.Composition.Attack.OriginalHash,["sourceRevision"]=1,["instances"]=new JArray(),["connections"]=new JArray()};for(int i=0;i<b.Composition.Attack.Formation.Slots.Count;i++){var c=b.Composition.Capture()["departure"]["cars"][i];((JArray)p["instances"]).Add(new JObject{["slot"]=i,["carriageId"]=c["instanceId"].DeepClone(),["sourceDefinitionId"]=c["carriageId"].DeepClone(),["generation"]=1,["positionMm"]=new JArray(i*span,0,0),["yawQuarterTurns"]=0});if(i>0)((JArray)p["connections"]).Add(new JObject{["fromSlot"]=i-1,["toSlot"]=i,["bridgeMm"]=new JArray(new JArray((i-1)*span+(long)asset["frontMm"][0],2400,0),new JArray(i*span+(long)asset["backMm"][0],2400,0))});}return BOrdinaryGeometryBinding.Read(p,BDirectAttackInput.Digest(p),g,b.Composition);}
  [Test] public void AuthoredMillimetreGeometryHasIndependentValidatedNativeSource(){var g=BOrdinaryGeometrySnapshot.Read(Asset(),BDirectAttackInput.Digest(Asset()));Assert.AreEqual("ordinary-b-test-carriage-v1",g.AssetId);var p=g.Capture();p["actorMm"][0]=1;Assert.IsFalse(JToken.DeepEquals(g.Capture(),p));}
