  internal static BDirectAttackBasicLoopBinding Stress(JObject p){var old=BInterceptSourceTests.Binding(p);var input=old.Composition.Attack.Capture();var flags=BindingFlags.Static|BindingFlags.NonPublic;var profile=(JObject)typeof(BDirectAttackBasicLoopTests).GetMethod("Owned",flags).Invoke(null,null);profile["accountId"]="a";var stat=((JArray)profile["operators"]).Single(x=>(string)x["operatorId"]=="op_kyle")["permanentStats"];stat["attack"]=new JObject{["numerator"]="50000",["denominator"]="1"};stat["maxHp"]=1000000;stat["basicIntervalMs"]=10;var e=((JArray)input["entities"]).Single(x=>(string)x["id"]=="op_kyle");e["attack"]=stat["attack"].DeepClone();e["maxHp"]=1000000;e["basicIntervalMicroseconds"]=10000;input["ownedProfileHash"]=BDirectAttackInput.Digest(profile);((JArray)input["sourceEvidence"]).Add(new JObject{["sourceId"]="U27_EXPLICIT_GEOMETRY_STRESS_PROFILE_NOT_OPERATING_STATS",["sha256"]=BDirectAttackInput.Digest(profile).Substring(7)});var source=BInterceptSourceTests.Read(p).OriginalSource.OriginalSource;var def=(CombatDefinitionIndex)typeof(BDirectAttackBasicLoopTests).GetMethod("Definition",flags).Invoke(null,null);var attack=BDirectAttackInput.ReadGunnerInterceptLocalRuntime(input,BDirectAttackInput.Digest(input),old.Composition.Attack.Formation,profile,BDirectAttackInput.Digest(profile),def,source);var c=old.Composition.Capture();c["attackInputHash"]=attack.OriginalHash;var composition=new BDirectAttackBuffBinding(attack,BInterceptSourceTests.Defs(),c,BDirectAttackInput.Digest(c));var routes=old.Capture();routes["compositionHash"]=composition.OriginalHash;routes["targets"]=new JArray(((JArray)routes["targets"]).Where(x=>(string)x["sourceId"]!="op_kyle").Select(x=>x.DeepClone()));return new BDirectAttackBasicLoopBinding(composition,routes,BDirectAttackInput.Digest(routes));}
  [Test] public void RealSpatialPositionsReplaceStaticGeometryAndBindNativeStep(){var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var b=Stress(p);var g=Geometry(b);var s=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);s.Advance("approach",10000000,500);var space=s.Capture()["spatialSource"];var life=((JArray)s.Capture()["boarding"]["lives"]).First(x=>(bool)x["registered"]);var frame=s.ObserveOrdinaryGeometry((string)life["id"],"op_kyle",s.Tick,(long)space["revision"],g.Hash);Assert.IsTrue((bool)s.Capture()["ordinaryRuntimeGeometrySupported"]);Assert.AreEqual(s.Tick,(long)frame["observedTick"]);Assert.AreNotEqual(6000,(long)frame["distanceMm"]);Assert.AreEqual(g.Hash,(string)frame["geometryHash"]);Assert.Throws<ArgumentException>(()=>s.ObserveOrdinaryGeometry((string)life["id"],"op_kyle",s.Tick-1,(long)space["revision"],g.Hash));Assert.Throws<ArgumentException>(()=>s.ObserveOrdinaryGeometry((string)life["id"],"op_kyle",s.Tick,(long)space["revision"],"wrong"));}
