  [Test] public void KillingCommandImmediatelyPublishesSameSpatialAndBoardingGeneration(){var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var b=Stress(p);var g=Geometry(b);var s=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);s.Advance("climbing",30000000,1500);string id=r.OriginalSource.OriginalSource.Waves[0].Instances[0].InstanceId;s.ApplyWaveBasic("kill","op_kyle",id,1);Assert.AreEqual(0,s.Hp(id));var board=((JArray)s.Capture()["boarding"]["lives"]).Single(x=>(string)x["id"]==id);var position=((JArray)s.Capture()["spatialSource"]["positions"]).Single(x=>(string)x["id"]==id);Assert.AreEqual((long)board["generation"],(long)position["generation"]);Assert.AreEqual("Dead",(string)position["phase"]);}
  [Test] public void AuthoredFireAndHitPointsAreObservedFromCurrentPose(){var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var b=Stress(p);var asset=Asset();asset["fireMm"]=new JArray(100,2400,0);asset["hitMm"]=new JArray(0,2400,200);var g=Geometry(b,asset);var s=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);s.Advance("entered",10000000,500);var space=s.Capture()["spatialSource"];string id=r.OriginalSource.OriginalSource.Waves[0].Instances[0].InstanceId;var f=s.ObserveOrdinaryGeometry("op_kyle",id,s.Tick,(long)space["revision"],g.Hash);Assert.AreEqual(100,(long)f["sourcePointMm"][0]);var back=s.ObserveOrdinaryGeometry(id,"op_kyle",s.Tick,(long)space["revision"],g.Hash);Assert.AreEqual(200,(long)back["targetPointMm"][2]);}
  [Test] public void MovingTargetDoesNotFreezeAnAlreadyWalkingEnemy(){var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var b=Stress(p);var g=Geometry(b);var s=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);s.Advance("roof",50000000,2500);string id=r.OriginalSource.OriginalSource.Waves[0].Instances[0].InstanceId;JToken Pose()=>((JArray)s.Capture()["spatialSource"]["positions"]).Single(x=>(string)x["id"]==id)["positionMm"];long before=(long)Pose()[0];s.MoveOrdinaryOperator("move","op_kyle",0,new JArray(6000,2400,0),g.Hash);s.Advance("chase",10000000,500);Assert.Greater((long)Pose()[0],before+500);}
  [Test] public void ActualTargetSelectionChangesAdmissionAndTimingTogether(){var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var f=((BDirectAttackBasicLoopBinding binding,BWaveBoardingLocalPaths paths))typeof(BWaveBoardingRuntimeTests).GetMethod("TwoOperatorFixture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{r.OriginalSource.OriginalSource,false,false});var asset=Asset();asset["bodyMinMm"][0]=-6000;asset["bodyMaxMm"][0]=6000;asset["roofMinMm"][0]=-6000;asset["roofMaxMm"][0]=6000;asset["frontMm"][0]=6000;asset["backMm"][0]=-6000;var g=Geometry(f.binding,asset);var s=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(f.binding,r.OriginalSource,g,10000,true);s.Advance("roof",100000000,5000);var space=(JArray)s.Capture()["spatialSource"]["positions"];var actors=(JArray)s.Capture()["enemyTiming"]["actors"];Assert.IsTrue(space.Any(x=>(string)x["targetId"]=="op_eve"),"Actual second-slot target must be observed");foreach(var position in space.Where(x=>x["targetId"].Type!=JTokenType.Null))Assert.AreEqual((string)position["targetId"],(string)actors.Single(x=>(string)x["sourceId"]==(string)position["id"])["targetId"]);}
  [Test] public void FarthestAnchorUsesAuthoredFireHitEndpoints(){var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var b=Stress(p);var a=Asset();a["hitMm"]=new JArray(-200,2400,0);a["gunnerAnchorsMm"]=new JArray{new JArray(24000,2400,0),new JArray(12000,2400,0)};var g=Geometry(b,a);var s=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);for(int i=0;i<400&&((JArray)s.Capture()["gunnerIntercept"]["projectiles"]).Count==0;i++)s.Advance("travel"+i,1000000,50);var shot=s.Capture()["gunnerIntercept"]["projectiles"][0];Assert.AreEqual(255,(long)shot["contactTick"]-(long)shot["launchTick"]);}
  [Test] public void NativeSpacePreservesPauseSpeedFramePartitionAndRejectsUnboundSource(){var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var b=Stress(p);var g=Geometry(b);var a=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);var c=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);a.Advance("whole",50000000,2500);for(int i=0;i<5;i++)c.Advance("part"+i,10000000,500);Assert.IsTrue(JToken.DeepEquals(a.Capture()["spatialSource"],c.Capture()["spatialSource"]));var before=a.Capture()["spatialSource"].DeepClone();a.SetPaused("pause",true);a.Advance("paused",10000000,500);Assert.IsTrue(JToken.DeepEquals(before,a.Capture()["spatialSource"]));a.SetPaused("resume",false);a.SetSpeed("double",4);a.Advance("fast",5000000,500);c.Advance("normal",10000000,500);Assert.IsTrue(JToken.DeepEquals(a.Capture()["spatialSource"],c.Capture()["spatialSource"]));var plain=BDirectAttackBasicLoop.CreateInterceptSourceRuntime(b,r.OriginalSource,BInterceptSourceTests.Paths(b.Composition.Attack),10000);Assert.Throws<ArgumentException>(()=>plain.ObserveOrdinaryGeometry("op_kyle","missing",0,0,g.Hash));}
