  public void ActualGunnerDistanceUsesMillimetresAndNativeFlightTicks(int distance,int ticks){var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var b=Stress(p);var a=Asset();a["gunnerAnchorsMm"]=new JArray{new JArray(distance,2400,0)};var g=Geometry(b,a);var s=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);for(int i=0;i<400&&((JArray)s.Capture()["gunnerIntercept"]["projectiles"]).Count==0;i++)s.Advance("travel"+i,1000000,50);var shot=s.Capture()["gunnerIntercept"]["projectiles"][0];Assert.AreEqual(ticks,(long)shot["contactTick"]-(long)shot["launchTick"]);}
  [Test] public void CrossCarOperatorChangesPhysicalSlotBeforeDestinationAndRestoresMidRoute(){
   var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var f=((BDirectAttackBasicLoopBinding binding,BWaveBoardingLocalPaths paths))typeof(BWaveBoardingRuntimeTests).GetMethod("TwoOperatorFixture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{r.OriginalSource.OriginalSource,false,false});var b=BWaveBoardingRuntimeTests.ManualOperators(f.binding);var g=Geometry(b);var s=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);
   s.MoveOrdinaryOperator("cross-car","op_mira",1,new JArray(24000,2400,0),g.Hash);s.Advance("bridge",135000000,1350);var pose=((JArray)s.Capture()["spatialSource"]["operators"]).Single(x=>(string)x["id"]=="op_mira");Assert.AreEqual(24300,(long)pose["positionMm"][0]);Assert.AreEqual(0,(int)pose["slot"],"Bridge retains last physical carriage until entering destination roof");
   s.Advance("entered-roof",15000000,150);pose=((JArray)s.Capture()["spatialSource"]["operators"]).Single(x=>(string)x["id"]=="op_mira");Assert.AreEqual(27000,(long)pose["positionMm"][0]);Assert.AreEqual(1,(int)pose["slot"],"Physical slot must change on roof entry, before the 73000mm endpoint");var cache=s.Capture();var clone=BDirectAttackBasicLoop.RestoreOrdinaryGeometryRuntime(cache,BDirectAttackInput.Digest(cache),b,r.OriginalSource,g,10000,true);s.MoveOrdinaryOperator("turn-back","op_mira",0,new JArray(0,2400,0),g.Hash);clone.MoveOrdinaryOperator("turn-back","op_mira",0,new JArray(0,2400,0),g.Hash);s.Advance("return",200000000,2000);clone.Advance("return",200000000,2000);Assert.IsTrue(JToken.DeepEquals(s.Capture(),clone.Capture()));
  }
  internal static BDirectAttackBasicLoopBinding CargoStress(JObject source){
   var old=Stress(source);var p=old.Composition.Attack.Capture();var form=new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,new[]{new BCombatSlot(old.Composition.Attack.Formation.Slots[0].CarriageId,"op_kyle"),new BCombatSlot("car1")});p["formation"]=form.Capture();var car=((JArray)p["entities"]).Single(x=>(string)x["kind"]=="CARRIAGE").DeepClone();car["id"]="car1";car["definitionId"]="LOCAL_ORIGINAL_car1";car["slot"]=1;((JArray)p["entities"]).Add(car);
   var flags=BindingFlags.Static|BindingFlags.NonPublic;var profile=(JObject)typeof(BDirectAttackBasicLoopTests).GetMethod("Owned",flags).Invoke(null,null);profile["accountId"]="a";var stat=((JArray)profile["operators"]).Single(x=>(string)x["operatorId"]=="op_kyle")["permanentStats"];stat["attack"]=new JObject{["numerator"]="50000",["denominator"]="1"};stat["maxHp"]=1000000;stat["basicIntervalMs"]=10;var definition=(CombatDefinitionIndex)typeof(BDirectAttackBasicLoopTests).GetMethod("Definition",flags).Invoke(null,null);var input=BDirectAttackInput.ReadGunnerInterceptLocalRuntime(p,BDirectAttackInput.Digest(p),form,profile,BDirectAttackInput.Digest(profile),definition,BInterceptSourceTests.Read(source).OriginalSource.OriginalSource);
   var c=old.Composition.Capture();c["attackInputHash"]=input.OriginalHash;var departure=c["departure"]["cars"][0].DeepClone();departure["slot"]=1;departure["instanceId"]="car1";departure["occupant"]=new JObject{["kind"]="CARGO"};((JArray)c["departure"]["cars"]).Add(departure);var state=c["initial"]["cars"][0].DeepClone();state["slot"]=1;state["actor"]="ABSENT";((JArray)c["initial"]["cars"]).Add(state);var composition=new BDirectAttackBuffBinding(input,old.Composition.Definitions,c,BDirectAttackInput.Digest(c));var routes=old.Capture();routes["compositionHash"]=composition.OriginalHash;return new BDirectAttackBasicLoopBinding(composition,routes,BDirectAttackInput.Digest(routes));
  }
  internal static JObject ShortCarAsset(){var a=Asset();a["operatorProbeSpeedMmPerSecond"]=10000;foreach(string field in new[]{"bodyMinMm","roofMinMm","backMm"})a[field][0]=-1000;foreach(string field in new[]{"bodyMaxMm","roofMaxMm","frontMm"})a[field][0]=1000;a["gunnerAnchorsMm"]=new JArray{new JArray(1000,2400,0)};return a;}
  [Test] public void EntrantsFindLivingOperatorOnCargoFromPhysicalOwner(){
   var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var b=CargoStress(p);var g=Geometry(b,ShortCarAsset());var s=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);s.MoveOrdinaryOperator("cargo-walk","op_kyle",1,new JArray(0,2400,0),g.Hash);s.Advance("before-entry",3000000,150);var op=((JArray)s.Capture()["spatialSource"]["operators"]).Single();Assert.AreEqual(1,(int)op["slot"]);s.Advance("first-entry",7000000,350);var lives=((JArray)s.Capture()["boarding"]["lives"]).Where(x=>(bool)x["registered"]).ToArray();Assert.Greater(lives.Length,0);Assert.IsTrue(lives.All(x=>(int)x["slot"]==0),"Existing entrances must not teleport when the operator moves");Assert.IsTrue(lives.All(x=>(string)x["phase"]=="GeometryPending"),"Empty physical carriage must repath toward the living operator on cargo");s.Advance("cargo-climb",200000000,10000);Assert.IsTrue(((JArray)s.Capture()["boarding"]["lives"]).Any(x=>(string)x["phase"]=="Rooftop"&&(int)x["slot"]==1));
  }
  [Test] public void KylePhysicalOwnCarEnvelopeRejectsNearbyEnemyOnOtherCar(){
   var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var b=CargoStress(p);var asset=ShortCarAsset();asset["gunnerAnchorsMm"]=new JArray{new JArray(800,2400,0)};var g=Geometry(b,asset);var s=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);s.MoveOrdinaryOperator("cargo","op_kyle",1,new JArray(-600,2400,0),g.Hash);s.Advance("live",200000000,10000);var space=s.Capture()["spatialSource"];File.WriteAllText("D:/Project/LASTRAIL/QA/CombatBMigration-20261004/OrdinaryGeometry/envelope-observation.json",space.ToString());var ids=r.OriginalSource.OriginalSource.Waves[0].Instances.Where(x=>x.DefinitionId=="enemy_spike_cart_gunner").Select(x=>x.InstanceId).ToArray();var gunner=((JArray)space["positions"]).First(x=>(string)x["phase"]=="Rooftop"&&(int)x["slot"]==0&&ids.Contains((string)x["id"]));string target=(string)gunner["id"];var frame=s.ObserveOrdinaryGeometry("op_kyle",target,s.Tick,(long)space["revision"],g.Hash);Assert.AreEqual(1,(int)frame["sourceSlot"]);Assert.AreEqual(0,(int)frame["targetSlot"]);Assert.LessOrEqual((long)frame["distanceMm"],1800);var before=s.Capture();Assert.Throws<InvalidOperationException>(()=>s.ApplyWaveBasic("outside-own-car","op_kyle",target,(long)gunner["generation"]));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()),"Rejected physical envelope must preserve native state");
  }
