   var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var b=Stress(p);var original=Geometry(b);var packet=original.Capture();packet["instances"][0]["positionMm"]=new JArray(1000,500,-3000);packet["instances"][0]["yawQuarterTurns"]=1;var asset=Asset();asset["scoutAnchorMm"]=new JArray(1200,2400,0);var definition=BOrdinaryGeometrySnapshot.Read(asset,BDirectAttackInput.Digest(asset));packet["geometryHash"]=definition.Hash;var g=BOrdinaryGeometryBinding.Read(packet,BDirectAttackInput.Digest(packet),definition,b.Composition);var s=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);s.Advance("roof",50000000,2500);var id=r.OriginalSource.OriginalSource.Waves[0].Instances.First(x=>x.DefinitionId=="enemy_raider_scout").InstanceId;var pose=((JArray)s.Capture()["spatialSource"]["positions"]).Single(x=>(string)x["id"]==id);Assert.AreEqual("Rooftop",(string)pose["phase"]);Assert.IsTrue(JToken.DeepEquals(new JArray(1000,2900,-1800),pose["routeMm"].Last),"Scout anchor must rotate with the original transform and consume authored offset");
