  [Test] public void NativeTargetDownRetargetsSurvivorWithoutRestartingOldProjectile(){
   var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var f=((BDirectAttackBasicLoopBinding binding,BWaveBoardingLocalPaths paths))typeof(BWaveBoardingRuntimeTests).GetMethod("TwoOperatorFixture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{r.OriginalSource.OriginalSource,false,false});var original=BWaveBoardingRuntimeTests.ManualOperators(f.binding);var input=original.Composition.Attack.Capture();var profile=(JObject)typeof(BDirectAttackBasicLoopTests).GetMethod("Owned",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);foreach(var op in new[]{"op_mira","op_eve"}){int hp=op=="op_mira"?1:1000000;((JArray)profile["operators"]).Single(x=>(string)x["operatorId"]==op)["permanentStats"]["maxHp"]=hp;((JArray)input["entities"]).Single(x=>(string)x["id"]==op)["maxHp"]=hp;}var attack=BWaveBoardingRuntimeTests.ReadWave(input,r.OriginalSource.OriginalSource,profile);var packet=original.Composition.Capture();packet["attackInputHash"]=attack.OriginalHash;var composition=new BDirectAttackBuffBinding(attack,original.Composition.Definitions,packet,BDirectAttackInput.Digest(packet));var routes=original.Capture();routes["compositionHash"]=composition.OriginalHash;var b=new BDirectAttackBasicLoopBinding(composition,routes,BDirectAttackInput.Digest(routes));var g=Geometry(b,ShortCarAsset());var s=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);s.Advance("native-down",100000000,1000);Assert.AreEqual(0,s.Hp("op_mira"));Assert.Greater(s.Hp("op_eve"),0);var spatial=s.Capture()["spatialSource"];var downFrame=s.ObserveOrdinaryGeometry("op_eve","op_mira",s.Tick,(long)spatial["revision"],g.Hash);Assert.AreEqual(2,(long)downFrame["targetGeneration"],"Spatial observations must use the original native target lifetime");var before=s.Capture();var shots=(JArray)before["gunnerIntercept"]["projectiles"];s.Advance("survivor",100000000,1000);var space=(JArray)s.Capture()["spatialSource"]["positions"];Assert.IsTrue(space.Any(x=>(string)x["targetId"]=="op_eve"));Assert.IsFalse(space.Any(x=>(string)x["targetId"]=="op_mira"));foreach(var shot in shots){var after=((JArray)s.Capture()["gunnerIntercept"]["projectiles"]).Single(x=>(string)x["id"]==(string)shot["id"]);Assert.AreEqual((long)shot["launchTick"],(long)after["launchTick"]);Assert.AreEqual((string)shot["targetId"],(string)after["targetId"]);}
  }
