  [Test] public void MovingTargetRepathUsesEnemyPhysicalSlotOnBoundaryTick(){var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var b=CargoStress(p);var g=Geometry(b,ShortCarAsset());var s=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);s.Advance("climb-before-target-move",20000000,1000);s.MoveOrdinaryOperator("cargo-target","op_kyle",1,new JArray(0,2400,0),g.Hash);var id=r.OriginalSource.OriginalSource.Waves[0].Instances.First(i=>i.DefinitionId=="enemy_raider_scout").InstanceId;JToken pose=null;for(int i=0;i<600;i++){s.Advance("find-boundary"+i,200000,10);pose=((JArray)s.Capture()["spatialSource"]["positions"]).FirstOrDefault(e=>(string)e["id"]==id);if(pose!=null&&(string)pose["phase"]=="Rooftop"&&(long)pose["positionMm"][0]>=1900)break;}Assert.NotNull(pose);Assert.Less((long)pose["positionMm"][0],2000);for(int i=0;i<50&&(long)pose["positionMm"][0]<1997;i++){s.Advance("near-entry"+i,20000,1);pose=((JArray)s.Capture()["spatialSource"]["positions"]).Single(e=>(string)e["id"]==id);}Assert.Less((long)pose["positionMm"][0],2000);s.MoveOrdinaryOperator("moving-chase","op_kyle",1,new JArray(1000,2400,0),g.Hash);for(int i=0;i<100;i++){s.Advance("boundary-step"+i,20000,1);pose=((JArray)s.Capture()["spatialSource"]["positions"]).Single(e=>(string)e["id"]==id);if((long)pose["positionMm"][0]>=2000)break;}Assert.GreaterOrEqual((long)pose["positionMm"][0],2000);Assert.AreEqual(1,(int)pose["slot"]);Assert.IsTrue(((JArray)pose["routeMm"]).All(e=>(long)e[0]>=2000),"A replacement path must not return through the previous carriage after entering this roof");}
