  [Test] public void SceneProbeRequiresLiveNativeOwnerAndIndependentVisibility(){var open=typeof(BOrdinaryGeometrySceneQa).GetMethod("Open",BindingFlags.Static|BindingFlags.NonPublic);Assert.NotNull(open,"Recorded JSON alone is insufficient; native owner binding is required");var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var b=Stress(p);var g=Geometry(b);var s=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);var probe=open.Invoke(null,new object[]{s,g});try {s.Advance("native",10000000,500);var show=probe.GetType().GetMethod("Show",BindingFlags.Instance|BindingFlags.NonPublic);show.Invoke(probe,new object[]{"scene-binding-test",false});var before=s.Capture();probe.GetType().GetMethod("AuditIndependentVisibility",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(probe,null);Assert.IsTrue(JToken.DeepEquals(before,s.Capture()),"View hide/replace must not mutate the original owner");}finally{((IDisposable)probe).Dispose();}var disposed=Assert.Throws<TargetInvocationException>(()=>probe.GetType().GetMethod("Show",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(probe,new object[]{"after-unbind",false}));Assert.IsInstanceOf<ObjectDisposedException>(disposed.InnerException);}
  [Test] public void OneOriginalSnapshotRunsClimbMovementInterceptHitTwoWavesAndRestore(){var p=BInterceptSourceTests.Sample();var r=BInterceptSourceTests.Read(p);var b=Stress(p);var g=Geometry(b);var s=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,r.OriginalSource,g,10000,true);using var probe=BOrdinaryGeometrySceneQa.Open(s,g);var stages=new JArray();void Stage(string name){probe.Show(name,true);stages.Add(new JObject{["name"]=name,["tick"]=s.Tick,["hp"]=s.Hp("op_kyle"),["spatial"]=s.Capture()["spatialSource"].DeepClone(),["boarding"]=s.Capture()["boarding"].DeepClone(),["projectiles"]=s.Capture()["gunnerIntercept"].DeepClone()});}s.Advance("enter",10000000,500);Stage("approach");Assert.AreEqual(4,((JArray)s.Capture()["boarding"]["lives"]).Count(x=>(bool)x["registered"]));s.Advance("climb",24000000,1200);Stage("climb-or-roof");int n=0;while(((JArray)s.Capture()["gunnerIntercept"]["projectiles"]).Count==0&&n<100)s.Advance("travel"+n++,1000000,50);Assert.Less(n,100,"No actual range/LOS launch after roof movement");Stage("launch");probe.AuditIndependentVisibility();string shot=(string)s.Capture()["gunnerIntercept"]["projectiles"][0]["id"];Assert.AreEqual(125,(long)s.Capture()["gunnerIntercept"]["projectiles"][0]["contactTick"]-(long)s.Capture()["gunnerIntercept"]["projectiles"][0]["launchTick"]);s.AcceptInterceptionSource("v3-accepted",shot,r);s.Advance("mid-flight",1000000,50);Stage("flight-mid");s.Advance("contact",1500000,75);Assert.AreEqual("INTERCEPTED",(string)s.Capture()["gunnerIntercept"]["projectiles"][0]["terminal"]);Stage("intercept");s.MoveOrdinaryOperator("probe-move","op_kyle",0,new JArray(6000,2400,0),g.Hash);var cache=s.Capture();var restored=BDirectAttackBasicLoop.RestoreOrdinaryGeometryRuntime(cache,BDirectAttackInput.Digest(cache),b,r.OriginalSource,g,10000,true);s.Advance("walk",40000000,2000);restored.Advance("walk",40000000,2000);Assert.IsTrue(JToken.DeepEquals(s.Capture(),restored.Capture()));Assert.Less(s.Hp("op_kyle"),1000000,"Actual native HP impact must occur in this same snapshot");Stage("walk-hit");int command=0;for(int pass=0;pass<500&&s.Outcome=="RUNNING";pass++){s.Advance("continue"+pass,1000000,50);foreach(var life in ((JArray)s.Capture()["boarding"]["lives"]).Where(x=>(bool)x["registered"]&&(bool)x["targetable"]).ToArray()){string id=(string)life["id"];var space=s.Capture()["spatialSource"];var frame=s.ObserveOrdinaryGeometry("op_kyle",id,s.Tick,(long)space["revision"],g.Hash);if(!(bool)frame["eligible"])continue;long due=(long)s.Capture()["state"]["direct"]["next"]["op_kyle"];if(due>s.Tick||s.Capture()["gunnerIntercept"]["interception"]["actions"].Any(a=>(string)a["phase"]=="PREPARATION"||(string)a["phase"]=="RECOVERY"&&s.Tick<(long)a["endTick"]))continue;s.ApplyWaveBasic("actual-hit"+command++,"op_kyle",id,(long)life["generation"]);}}
   Assert.AreEqual("VICTORY",s.Outcome);Assert.AreEqual(2,((JArray)s.Capture()["waveEntry"]["events"]).Count(x=>(string)x["kind"]=="WAVE_CLEAR"));Assert.IsTrue(((JArray)s.Capture()["boarding"]["events"]).Any(x=>(string)x["kind"]=="SOCKET_RETURN_ROOF"));Assert.IsFalse(((JArray)s.Capture()["gunnerIntercept"]["projectiles"]).Any(x=>(string)x["terminal"]=="FLYING"));Stage("two-waves-complete");var end=s.Capture();restored=BDirectAttackBasicLoop.RestoreOrdinaryGeometryRuntime(end,BDirectAttackInput.Digest(end),b,r.OriginalSource,g,10000,true);Assert.IsTrue(JToken.DeepEquals(end,restored.Capture()));string folder=BOrdinaryGeometrySceneQa.OutputFolder;Directory.CreateDirectory(folder);File.WriteAllText(folder+"/continuous-stages.json",stages.ToString());File.WriteAllText(folder+"/continuous-final.json",end.ToString());
  }
